-- =============================================================================
-- Migration 0071: K.3 A t/m K.3 C — aanvullen tot 8 vragen per soort
-- =============================================================================
-- Gegenereerd door scripts/k3-aanvullen-8.ts — niet met de hand bewerken.
--
-- K.3 A en K.3 B hadden zes vragen per soort. K.3 C had er drie tot vijf.
-- Deze migratie vult elk cluster aan tot acht, met eigen varianten.
-- K.4 en K.5 hadden al acht vragen en blijven buiten deze migratie.
--
-- De controle verwacht ná deze migratie acht vragen per cluster. De
-- stappencontrole telt alleen de nieuwe opgaven.
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 10 topics, 17 clusters
--   • 50 vragen met elk 4 stappen (200 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k3a_arctangens', $ksql$De functie arctan$ksql$, 17, 'vergelijkingen'),
  ('k3a_primitiveren', $ksql$Primitiveren met arctan$ksql$, 18, 'primitiveren'),
  ('k3a_bepaald', $ksql$Bepaalde integralen met arctan$ksql$, 19, 'integralen'),
  ('k3b_primitiveren', $ksql$Primitiveren naar arctan: de vorm zoeken$ksql$, 20, 'primitiveren'),
  ('k3b_bepaald', $ksql$Bepaalde integralen naar arctan$ksql$, 21, 'integralen'),
  ('k3b_toepassing', $ksql$Vlakdelen met arctan$ksql$, 22, 'toepassingen'),
  ('k3c_arcsinus', $ksql$De functie arcsin$ksql$, 23, 'vergelijkingen'),
  ('k3c_primitiveren', $ksql$Primitiveren naar arcsin$ksql$, 24, 'primitiveren'),
  ('k3c_bepaald', $ksql$Bepaalde integralen met arcsin$ksql$, 25, 'integralen'),
  ('k3c_toepassing', $ksql$Vlakdelen met arcsin$ksql$, 26, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k3a_arctangens', 'k3a_waarden', $ksql$Exacte waarden van arctan$ksql$, 1),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Vergelijkingen met arctan oplossen$ksql$, 2),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$De afgeleide van arctan$ksql$, 1),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$De standaardvorm 1/(x² + 1) primitiveren$ksql$, 2),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Een kern in de noemer$ksql$, 3),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bepaalde integralen met arctan$ksql$, 1),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Naar de vorm a/((bx)² + 1)$ksql$, 1),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Kwadraatafsplitsen in de noemer$ksql$, 2),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bepaalde integralen met arctan$ksql$, 1),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Oppervlakte en de waarde van p$ksql$, 1),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Exacte waarden van arcsin$ksql$, 1),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Vergelijkingen met arcsin oplossen$ksql$, 2),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$De standaardvorm 1/√(1 - x²) primitiveren$ksql$, 1),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Een kern onder de wortel$ksql$, 2),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$arcsin en arctan partieel integreren$ksql$, 3),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bepaalde integralen met arcsin$ksql$, 1),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Oppervlakte en de waarde van p$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

