  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(2x)$$ksql$, $ksql$x arctan(2x) - 1/4 ln(4x^2 + 1) + c$ksql$, $ksql$F(x) = x\arctan(2x) - \tfrac{1}{4}\ln\left(4x^{2} + 1\right) + c$ksql$, 3, 7, ARRAY[$ksql$x atan(2x) - ln(4x^2 + 1)/4 + c$ksql$, $ksql$x*arctan(2x) - 1/4*ln(4x^2+1) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \arcsin(2x)\,\mathrm{d}x$$ksql$, $ksql$1/4 pi - 1/2$ksql$, $ksql$\tfrac{1}{4}\pi - \tfrac{1}{2}$ksql$, 3, 8, ARRAY[$ksql$pi/4 - 1/2$ksql$, $ksql$(1/4)pi - 0,5$ksql$, $ksql$pi/4 - 0.5$ksql$, $ksql$-1/2 + 1/4 pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, $ksql$1/6 pi$ksql$, $ksql$\tfrac{1}{6}\pi$ksql$, 1, 5, ARRAY[$ksql$pi/6$ksql$, $ksql$(1/6)pi$ksql$, $ksql$1/6pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, $ksql$1/2 pi$ksql$, $ksql$\tfrac{1}{2}\pi$ksql$, 2, 6, ARRAY[$ksql$pi/2$ksql$, $ksql$(1/2)pi$ksql$, $ksql$1/2pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$$ksql$, $ksql$1/2 pi$ksql$, $ksql$\tfrac{1}{2}\pi$ksql$, 2, 7, ARRAY[$ksql$pi/2$ksql$, $ksql$(1/2)pi$ksql$, $ksql$1/2pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{\sqrt{4 - x^{4}}}\,\mathrm{d}x$$ksql$, $ksql$1/6 pi$ksql$, $ksql$\tfrac{1}{6}\pi$ksql$, 3, 8, ARRAY[$ksql$pi/6$ksql$, $ksql$(1/6)pi$ksql$, $ksql$1/6pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = \tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$1/6 pi$ksql$, $ksql$\tfrac{1}{6}\pi$ksql$, 1, 4, ARRAY[$ksql$pi/6$ksql$, $ksql$(1/6)pi$ksql$, $ksql$1/6pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$1/3 pi$ksql$, $ksql$\tfrac{1}{3}\pi$ksql$, 2, 5, ARRAY[$ksql$pi/3$ksql$, $ksql$(1/3)pi$ksql$, $ksql$1/3pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = -2$ en $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$pi$ksql$, $ksql$\pi$ksql$, 2, 6, ARRAY[$ksql$π$ksql$, $ksql$1pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 1$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{3}\pi$.$ksql$, $ksql$1/2$ksql$, $ksql$p = \tfrac{1}{2}$ksql$, 3, 7, ARRAY[$ksql$p = 1/2$ksql$, $ksql$0,5$ksql$, $ksql$0.5$ksql$, $ksql$p = 0,5$ksql$, $ksql$p = 0.5$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{6}{\sqrt{36 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 6$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, $ksql$3$ksql$, $ksql$p = 3$ksql$, 3, 8, ARRAY[$ksql$p = 3$ksql$, $ksql$p=3$ksql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(-\sqrt{3}\right) + \arctan(1)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(-\sqrt{3}\right) + \arctan(1)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. Je telt twee hoeken bij elkaar op. Zoek ze elk apart in de tabel en tel daarna.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(-\sqrt{3}\right) + \arctan(1)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$, $\tan\left(\tfrac{1}{4}\pi\right) = 1$ en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Omdat $\tan$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. $\arctan\left(-\sqrt{3}\right) = -\tfrac{1}{3}\pi$ en $\arctan(1) = \tfrac{1}{4}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(-\sqrt{3}\right) + \arctan(1)$$ksql$, 3, $ksql$Samen: $-\tfrac{1}{3}\pi + \tfrac{1}{4}\pi = -\tfrac{4}{12}\pi + \tfrac{3}{12}\pi = -\tfrac{1}{12}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. Eerst de tangens uitrekenen, en daarna pas $\arctan$. De hoek $\tfrac{5}{6}\pi$ ligt buiten het gebied van $\arctan$, dus het antwoord is niet vanzelf $\tfrac{5}{6}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$, $\tan\left(\tfrac{1}{4}\pi\right) = 1$ en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Omdat $\tan$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. $\tan\left(\tfrac{5}{6}\pi\right) = \tan\left(\pi - \tfrac{1}{6}\pi\right) = -\tan\left(\tfrac{1}{6}\pi\right) = -\tfrac{1}{3}\sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 3, $ksql$$\arctan\left(-\tfrac{1}{3}\sqrt{3}\right) = -\tfrac{1}{6}\pi$, want die hoek ligt wél tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ en heeft dezelfde tangens.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $2\arctan(x) = \tfrac{1}{3}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: een veelvoud van $\arctan(x)$ is gelijk aan een hoek uit de tabel → eerst $\arctan(x)$ vrijmaken.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $2\arctan(x) = \tfrac{1}{3}\pi$$ksql$, 1, $ksql$Deel door $2$: $\arctan(x) = \tfrac{1}{6}\pi$. Die hoek ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus er is een oplossing.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $2\arctan(x) = \tfrac{1}{3}\pi$$ksql$, 2, $ksql$Tangens nemen: $x = \tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $2\arctan(x) = \tfrac{1}{3}\pi$$ksql$, 3, $ksql$Dus $x = \tfrac{1}{3}\sqrt{3}$. Controle: $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) = \tfrac{1}{6}\pi$, en twee keer die hoek is $\tfrac{1}{3}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(3x) = 1{,}2$. Rond af op drie decimalen.$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van een kern is gelijk aan een getal → eerst de kern vrijmaken. Rechts staat $1{,}2$ in radialen, geen hoek uit de tabel.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(3x) = 1{,}2$. Rond af op drie decimalen.$ksql$, 1, $ksql$Kan het? $1{,}2 < \tfrac{1}{2}\pi \approx 1{,}571$, dus $1{,}2$ ligt in het bereik van $\arctan$ en er is een oplossing. Tangens nemen geeft $3x = \tan(1{,}2)$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(3x) = 1{,}2$. Rond af op drie decimalen.$ksql$, 2, $ksql$Dus $x = \dfrac{\tan(1{,}2)}{3}$. Dat is de exacte oplossing; $1{,}2$ staat niet in de tabel.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(3x) = 1{,}2$. Rond af op drie decimalen.$ksql$, 3, $ksql$Met de rekenmachine (in radialen!): $\tan(1{,}2) \approx 2{,}5722$, dus $x \approx \dfrac{2{,}5722}{3} \approx 0{,}857$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(5x - 1)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is precies de standaardvorm die je bij deel 2 van de driedeling moet herkennen: $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Daarom oefen je hem eerst andersom. Buitenste schil: $\arctan$ van een kern → kettingregel.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(5x - 1)$$ksql$, 1, $ksql$Buitenkant en kern: buitenkant $\arctan(\ldots)$, kern $5x - 1$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(5x - 1)$$ksql$, 2, $ksql$Afgeleide van de buitenkant met de kern erin: $\dfrac{1}{(5x - 1)^{2} + 1}$. Afgeleide van de kern: $5$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(5x - 1)$$ksql$, 3, $ksql$Vermenigvuldig: $f'(x) = \dfrac{5}{(5x - 1)^{2} + 1}$. Werk het kwadraat uit: $(5x - 1)^{2} + 1 = 25x^{2} - 10x + 2$, dus $f'(x) = \dfrac{5}{25x^{2} - 10x + 2}$. Controle: de afgeleide van $\arctan$ van de kern, maal de afgeleide van de kern, geeft precies deze breuk terug.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x^{2}\arctan(x)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is $\dfrac{1}{x^{2} + 1}$. Hier staat een product van $x^{2}$ en $\arctan(x)$, dus de productregel: $(g \cdot h)' = g' \cdot h + g \cdot h'$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x^{2}\arctan(x)$$ksql$, 1, $ksql$Neem $g(x) = x^{2}$ en $h(x) = \arctan(x)$. Dan is $g'(x) = 2x$ en $h'(x) = \dfrac{1}{x^{2} + 1}$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x^{2}\arctan(x)$$ksql$, 2, $ksql$Vul in: $f'(x) = 2x \cdot \arctan(x) + x^{2} \cdot \dfrac{1}{x^{2} + 1}$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x^{2}\arctan(x)$$ksql$, 3, $ksql$Schrijf het antwoord op: $f'(x) = 2x\arctan(x) + \dfrac{x^{2}}{x^{2} + 1}$. Controle: differentieer $x^{2}\arctan(x)$ met de productregel en je krijgt deze twee termen terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2} + 1}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2} + 1}{x^{2} + 1}$$ksql$, 1, $ksql$De teller is nog geen veelvoud van de noemer. Schrijf $3x^{2} + 1 = 3(x^{2} + 1) - 2$, dus $f(x) = 3 - \dfrac{2}{x^{2} + 1}$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2} + 1}{x^{2} + 1}$$ksql$, 2, $ksql$De constante $3$ geeft $3x$. En $\dfrac{2}{x^{2} + 1}$ geeft $2\arctan(x)$, met een minteken ervoor.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2} + 1}{x^{2} + 1}$$ksql$, 3, $ksql$Dus $F(x) = 3x - 2\arctan(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6x - 2}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6x - 2}{x^{2} + 1}$$ksql$, 1, $ksql$Splits de breuk: $f(x) = \dfrac{6x}{x^{2} + 1} - \dfrac{2}{x^{2} + 1}$. De eerste term hoort bij $\ln$, de tweede bij $\arctan$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6x - 2}{x^{2} + 1}$$ksql$, 2, $ksql$$\left[\ln\left(x^{2} + 1\right)\right]' = \dfrac{2x}{x^{2} + 1}$, dus $\dfrac{6x}{x^{2} + 1}$ is daar drie keer van en geeft $3\ln\left(x^{2} + 1\right)$. En $\dfrac{2}{x^{2} + 1}$ geeft $2\arctan(x)$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6x - 2}{x^{2} + 1}$$ksql$, 3, $ksql$Dus $F(x) = 3\ln\left(x^{2} + 1\right) - 2\arctan(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(3x + 1)^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(3x + 1)^{2} + 1}$$ksql$, 1, $ksql$Er staat al een kwadraat plus $1$. De kern is $3x + 1$, dus $a = 3$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(3x + 1)^{2} + 1}$$ksql$, 2, $ksql$De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$ met de kern erin geeft $\arctan(3x + 1)$. Delen door $3$ zet er $\tfrac{1}{3}$ voor.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(3x + 1)^{2} + 1}$$ksql$, 3, $ksql$Dus $F(x) = \tfrac{1}{3}\arctan(3x + 1) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{4x^{3}}{x^{8} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: in de noemer staat het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{g^{2} + 1}\,\mathrm{d}x = \arctan(g) + c$ ben je er in één stap.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{4x^{3}}{x^{8} + 1}$$ksql$, 1, $ksql$Neem $g(x) = x^{4}$. Dan is $g'(x) = 4x^{3}$, en die staat precies in de teller. In de noemer staat $(x^{4})^{2} + 1 = g^{2} + 1$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{4x^{3}}{x^{8} + 1}$$ksql$, 2, $ksql$Naar $g$ staat er $\int \dfrac{1}{g^{2} + 1}\,\mathrm{d}g = \arctan(g)$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{4x^{3}}{x^{8} + 1}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arctan\left(x^{4}\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Er staat al de standaardvorm. De bovengrens $\sqrt{3}$ is een hint dat er straks een hoek uit de tabel komt.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $F(x) = \arctan(x)$, zonder integratieconstante — bij een bepaalde integraal valt die toch weg.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\big[\arctan(x)\big]_{0}^{\sqrt{3}} = \arctan\left(\sqrt{3}\right) - \arctan(0) = \tfrac{1}{3}\pi - 0 = \tfrac{1}{3}\pi$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{4x^{3}}{x^{8} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: in de noemer staat het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{g^{2} + 1}\,\mathrm{d}x = \arctan(g) + c$ ben je er in één stap.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{4x^{3}}{x^{8} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Neem $g(x) = x^{4}$. Dan is $g'(x) = 4x^{3}$ en de noemer is $g^{2} + 1$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{4x^{3}}{x^{8} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $F(x) = \arctan\left(x^{4}\right)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{4x^{3}}{x^{8} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\big[\arctan\left(x^{4}\right)\big]_{0}^{1} = \arctan(1) - \arctan(0) = \tfrac{1}{4}\pi - 0 = \tfrac{1}{4}\pi$.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{4}{x^{2} + 4}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een getal in de teller en $px^{2} + q$ in de noemer → nog geen standaardvorm, want achter het kwadraat staat niet $1$. Deel eerst teller en noemer door $q$, zodat er $\dfrac{a}{(bx)^{2} + 1}$ komt te staan.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{4}{x^{2} + 4}$$ksql$, 1, $ksql$Deel teller en noemer door $4$: $f(x) = \dfrac{1}{\tfrac{1}{4}x^{2} + 1} = \dfrac{1}{\left(\tfrac{1}{2}x\right)^{2} + 1}$. Kern $\tfrac{1}{2}x$, dus $a = \tfrac{1}{2}$.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{4}{x^{2} + 4}$$ksql$, 2, $ksql$De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Delen door $\tfrac{1}{2}$ is vermenigvuldigen met $2$, dus er komt $2\arctan\left(\tfrac{1}{2}x\right)$.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{4}{x^{2} + 4}$$ksql$, 3, $ksql$Dus $F(x) = 2\arctan\left(\tfrac{1}{2}x\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 8}{x^{2} + 4}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een getal in de teller en $px^{2} + q$ in de noemer → nog geen standaardvorm, want achter het kwadraat staat niet $1$. Deel eerst teller en noemer door $q$, zodat er $\dfrac{a}{(bx)^{2} + 1}$ komt te staan.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 8}{x^{2} + 4}$$ksql$, 1, $ksql$Deel eerst de teller door de noemer: $x^{2} + 8 = (x^{2} + 4) + 4$, dus $f(x) = 1 + \dfrac{4}{x^{2} + 4}$. Daarna de tweede term naar de standaardvorm: $\dfrac{4}{x^{2} + 4} = \dfrac{1}{\left(\tfrac{1}{2}x\right)^{2} + 1}$.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 8}{x^{2} + 4}$$ksql$, 2, $ksql$De $1$ geeft $x$. De breuk heeft kern $\tfrac{1}{2}x$, dus delen door $\tfrac{1}{2}$ geeft $2\arctan\left(\tfrac{1}{2}x\right)$.$ksql$),
  ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 8}{x^{2} + 4}$$ksql$, 3, $ksql$Dus $F(x) = x + 2\arctan\left(\tfrac{1}{2}x\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 6x + 10}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een polynoom $x^{2} + bx + c$ waar geen kwadraat in te zien is → eerst kwadraatafsplitsen, en dan pas kijken welke standaardvorm erbij hoort.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 6x + 10}$$ksql$, 1, $ksql$Kwadraatafsplitsen: neem de helft van het getal voor $x$, zet dat in het kwadraat, en corrigeer met een getal. De helft van $6$ is $3$: $(x + 3)^{2} = x^{2} + 6x + 9$, dus $x^{2} + 6x + 10 = (x + 3)^{2} + 1$.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 6x + 10}$$ksql$, 2, $ksql$Er staat nu precies de standaardvorm met kern $x + 3$ en $a = 1$. Delen door $1$ verandert niets: $\arctan(x + 3)$.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 6x + 10}$$ksql$, 3, $ksql$Dus $F(x) = \arctan(x + 3) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{8}{x^{2} - 2x + 5}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een polynoom $x^{2} + bx + c$ waar geen kwadraat in te zien is → eerst kwadraatafsplitsen, en dan pas kijken welke standaardvorm erbij hoort.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{8}{x^{2} - 2x + 5}$$ksql$, 1, $ksql$Kwadraatafsplitsen: neem de helft van het getal voor $x$, zet dat in het kwadraat, en corrigeer met een getal. De helft van $-2$ is $-1$: $(x - 1)^{2} = x^{2} - 2x + 1$, dus $x^{2} - 2x + 5 = (x - 1)^{2} + 4$. Haal de $4$ eruit: $(x - 1)^{2} + 4 = 4\left(\left(\tfrac{1}{2}(x - 1)\right)^{2} + 1\right)$. De breuk wordt $\dfrac{8}{4\left(\left(\tfrac{1}{2}(x - 1)\right)^{2} + 1\right)} = \dfrac{2}{\left(\tfrac{1}{2}(x - 1)\right)^{2} + 1}$.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{8}{x^{2} - 2x + 5}$$ksql$, 2, $ksql$Kern $\tfrac{1}{2}(x - 1)$, dus $a = \tfrac{1}{2}$. De factor $2$ maal delen door $\tfrac{1}{2}$ geeft $2 \cdot 2 = 4$ ervoor.$ksql$),
  ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{8}{x^{2} - 2x + 5}$$ksql$, 3, $ksql$Dus $F(x) = 4\arctan\left(\tfrac{1}{2}(x - 1)\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{x^{2} + 9}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met een getal in de teller en $px^{2} + q$ in de noemer → nog geen standaardvorm, want achter het kwadraat staat niet $1$. Deel eerst teller en noemer door $q$, zodat er $\dfrac{a}{(bx)^{2} + 1}$ komt te staan.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{x^{2} + 9}\,\mathrm{d}x$$ksql$, 1, $ksql$Deel teller en noemer door $9$: $\dfrac{1}{x^{2} + 9} = \dfrac{\tfrac{1}{9}}{\left(\tfrac{1}{3}x\right)^{2} + 1}$. Kern $\tfrac{1}{3}x$, dus $a = \tfrac{1}{3}$.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{x^{2} + 9}\,\mathrm{d}x$$ksql$, 2, $ksql$Delen door $\tfrac{1}{3}$ is vermenigvuldigen met $3$, en $\tfrac{1}{9} \cdot 3 = \tfrac{1}{3}$. Een primitieve is $F(x) = \tfrac{1}{3}\arctan\left(\tfrac{1}{3}x\right)$.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{x^{2} + 9}\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = 3$ is de kern $1$ en bij $x = 0$ is de kern $0$: $\tfrac{1}{3}\arctan(1) - \tfrac{1}{3}\arctan(0) = \tfrac{1}{3} \cdot \tfrac{1}{4}\pi = \tfrac{1}{12}\pi$.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{1}^{1 + \sqrt{3}} \dfrac{3}{x^{2} - 2x + 2}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met in de noemer een polynoom $x^{2} + bx + c$ waar geen kwadraat in te zien is → eerst kwadraatafsplitsen, en dan pas kijken welke standaardvorm erbij hoort.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{1}^{1 + \sqrt{3}} \dfrac{3}{x^{2} - 2x + 2}\,\mathrm{d}x$$ksql$, 1, $ksql$Kwadraatafsplitsen: neem de helft van het getal voor $x$, zet dat in het kwadraat, en corrigeer met een getal. $x^{2} - 2x + 2 = (x - 1)^{2} + 1$. Er staat dus $\dfrac{3}{(x - 1)^{2} + 1}$, met kern $x - 1$ en $a = 1$.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{1}^{1 + \sqrt{3}} \dfrac{3}{x^{2} - 2x + 2}\,\mathrm{d}x$$ksql$, 2, $ksql$De factor $3$ blijft ervoor staan: $F(x) = 3\arctan(x - 1)$.$ksql$),
  ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{1}^{1 + \sqrt{3}} \dfrac{3}{x^{2} - 2x + 2}\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = 1 + \sqrt{3}$ is de kern $\sqrt{3}$ en bij $x = 1$ is de kern $0$: $3\arctan\left(\sqrt{3}\right) - 3\arctan(0) = 3 \cdot \tfrac{1}{3}\pi = \pi$.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Gegeven is de functie $f(x) = \dfrac{18}{x^{2} + 6x + 18}$. Bereken exact het maximum van $f$.$ksql$, 0, $ksql$Er zit geen integraal in deze opgave, maar wel precies dezelfde eerste stap als bij het primitiveren: kwadraatafsplitsen in de noemer. Daarna zie je het antwoord zo staan.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Gegeven is de functie $f(x) = \dfrac{18}{x^{2} + 6x + 18}$. Bereken exact het maximum van $f$.$ksql$, 1, $ksql$Kwadraatafsplitsen: neem de helft van het getal voor $x$, zet dat in het kwadraat, en corrigeer met een getal. De helft van $6$ is $3$: $(x + 3)^{2} = x^{2} + 6x + 9$, dus $x^{2} + 6x + 18 = (x + 3)^{2} + 9$. Dus $f(x) = \dfrac{18}{(x + 3)^{2} + 9}$.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Gegeven is de functie $f(x) = \dfrac{18}{x^{2} + 6x + 18}$. Bereken exact het maximum van $f$.$ksql$, 2, $ksql$De teller staat vast, dus $f$ is het grootst waar de noemer het kleinst is. Een kwadraat is nooit negatief, dus $(x + 3)^{2} + 9$ is het kleinst als $(x + 3)^{2} = 0$, en dat is bij $x = -3$. De noemer is daar $9$.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Gegeven is de functie $f(x) = \dfrac{18}{x^{2} + 6x + 18}$. Bereken exact het maximum van $f$.$ksql$, 3, $ksql$Dus het maximum is $f(-3) = \dfrac{18}{9} = 2$. Voor elke andere $x$ is de noemer groter dan $9$ en de breuk dus kleiner dan $2$.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{2}\pi$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V_p) = \displaystyle\int_{0}^{p} \dfrac{4}{x^{2} + 4}\,\mathrm{d}x$. Op $[0, p]$ is $f$ positief.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{2}\pi$.$ksql$, 1, $ksql$$\dfrac{4}{x^{2} + 4} = \dfrac{1}{\left(\tfrac{1}{2}x\right)^{2} + 1}$, met kern $\tfrac{1}{2}x$ en $a = \tfrac{1}{2}$.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{2}\pi$.$ksql$, 2, $ksql$Deel 2: delen door $\tfrac{1}{2}$ geeft $F(x) = 2\arctan\left(\tfrac{1}{2}x\right)$. Omdat $\arctan(0) = 0$ is $O(V_p) = 2\arctan\left(\tfrac{1}{2}p\right)$.$ksql$),
  ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{2}\pi$.$ksql$, 3, $ksql$Deel 3: $2\arctan\left(\tfrac{1}{2}p\right) = \tfrac{1}{2}\pi$ geeft $\arctan\left(\tfrac{1}{2}p\right) = \tfrac{1}{4}\pi$. Dus $\tfrac{1}{2}p = \tan\left(\tfrac{1}{4}\pi\right) = 1$ en $p = 2$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\right)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Zoek de hoek in de tabel waarvan de sinus $\tfrac{1}{2}$ is.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\right)$$ksql$, 3, $ksql$$\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$ en $\tfrac{1}{6}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus $\arcsin\left(\tfrac{1}{2}\right) = \tfrac{1}{6}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin(-1)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin(-1)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Zoek de hoek waarvan de sinus $-1$ is. Omdat $\sin$ oneven is, hoort bij $-1$ de tegenovergestelde hoek van $\arcsin(1)$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin(-1)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. $\arcsin(1) = \tfrac{1}{2}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin(-1)$$ksql$, 3, $ksql$Dus $\arcsin(-1) = -\tfrac{1}{2}\pi$. Dat is meteen de onderkant van het bereik van $\arcsin$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{2}\right) + \arcsin\left(-\tfrac{1}{2}\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{2}\right) + \arcsin\left(-\tfrac{1}{2}\right)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Twee hoeken apart opzoeken en daarna optellen.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{2}\right) + \arcsin\left(-\tfrac{1}{2}\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. $\arcsin\left(\tfrac{1}{2}\sqrt{2}\right) = \tfrac{1}{4}\pi$ en $\arcsin\left(-\tfrac{1}{2}\right) = -\tfrac{1}{6}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{2}\right) + \arcsin\left(-\tfrac{1}{2}\right)$$ksql$, 3, $ksql$Samen: $\tfrac{1}{4}\pi - \tfrac{1}{6}\pi = \tfrac{3}{12}\pi - \tfrac{2}{12}\pi = \tfrac{1}{12}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $2\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) - \arcsin(1)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $2\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) - \arcsin(1)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Eerst de twee hoeken uit de tabel, daarna het verschil.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $2\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) - \arcsin(1)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) = \tfrac{1}{3}\pi$ en $\arcsin(1) = \tfrac{1}{2}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $2\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) - \arcsin(1)$$ksql$, 3, $ksql$$2 \cdot \tfrac{1}{3}\pi - \tfrac{1}{2}\pi = \tfrac{2}{3}\pi - \tfrac{1}{2}\pi = \tfrac{4}{6}\pi - \tfrac{3}{6}\pi = \tfrac{1}{6}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{7}{6}\pi\right)\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{7}{6}\pi\right)\right)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Eerst de sinus uitrekenen. De hoek $\tfrac{7}{6}\pi$ ligt buiten het bereik van $\arcsin$, dus het antwoord is niet vanzelf $\tfrac{7}{6}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{7}{6}\pi\right)\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. $\sin\left(\tfrac{7}{6}\pi\right) = \sin\left(\pi + \tfrac{1}{6}\pi\right) = -\sin\left(\tfrac{1}{6}\pi\right) = -\tfrac{1}{2}$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{7}{6}\pi\right)\right)$$ksql$, 3, $ksql$$\arcsin\left(-\tfrac{1}{2}\right) = -\tfrac{1}{6}\pi$, want die hoek ligt wél tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{4}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin(x)$ is gelijk aan een hoek uit de tabel → sinus nemen.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{4}\pi$$ksql$, 1, $ksql$$\tfrac{1}{4}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus er is een oplossing.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{4}\pi$$ksql$, 2, $ksql$$x = \sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{4}\pi$$ksql$, 3, $ksql$Dus $x = \tfrac{1}{2}\sqrt{2}$. Die waarde ligt tussen $-1$ en $1$, dus hij mag in $\arcsin$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(2x) = -\tfrac{1}{6}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin$ van een kern is gelijk aan een hoek → eerst sinus nemen, daarna de kern vrijmaken.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(2x) = -\tfrac{1}{6}\pi$$ksql$, 1, $ksql$$-\tfrac{1}{6}\pi$ ligt in het bereik van $\arcsin$. Sinus nemen geeft $2x = \sin\left(-\tfrac{1}{6}\pi\right) = -\tfrac{1}{2}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(2x) = -\tfrac{1}{6}\pi$$ksql$, 2, $ksql$Dus $x = -\tfrac{1}{4}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(2x) = -\tfrac{1}{6}\pi$$ksql$, 3, $ksql$Controle: $2x = -\tfrac{1}{2}$ ligt tussen $-1$ en $1$, en $\arcsin\left(-\tfrac{1}{2}\right) = -\tfrac{1}{6}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin$ van iets is gelijk aan een hoek → kijk eerst of die hoek überhaupt kan.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \pi$$ksql$, 1, $ksql$Het bereik van $\arcsin$ is $\left[-\tfrac{1}{2}\pi, \tfrac{1}{2}\pi\right]$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \pi$$ksql$, 2, $ksql$$\pi$ is groter dan $\tfrac{1}{2}\pi$, dus die waarde wordt nooit bereikt.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \pi$$ksql$, 3, $ksql$De vergelijking heeft geen oplossing. Schrijf niet $x = \sin(\pi) = 0$ op: $\arcsin(0)$ is $0$ en niet $\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = 0{,}8$. Rond af op drie decimalen.$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin(x)$ is gelijk aan een getal in radialen → sinus nemen. $0{,}8$ staat niet in de tabel.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = 0{,}8$. Rond af op drie decimalen.$ksql$, 1, $ksql$Kan het? $0{,}8 < \tfrac{1}{2}\pi \approx 1{,}571$, dus $0{,}8$ ligt in het bereik en er is een oplossing.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = 0{,}8$. Rond af op drie decimalen.$ksql$, 2, $ksql$$x = \sin(0{,}8)$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = 0{,}8$. Rond af op drie decimalen.$ksql$, 3, $ksql$Met de rekenmachine (in radialen!): $\sin(0{,}8) \approx 0{,}7174$, afgerond op drie decimalen $x \approx 0{,}717$. Die waarde ligt tussen $-1$ en $1$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 9x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 9x^{2}}}$$ksql$, 1, $ksql$$9x^{2} = (3x)^{2}$, dus er staat $\dfrac{1}{\sqrt{1 - (3x)^{2}}}$: kern $3x$ met $a = 3$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 9x^{2}}}$$ksql$, 2, $ksql$De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Delen door $3$ zet er $\tfrac{1}{3}$ voor.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 9x^{2}}}$$ksql$, 3, $ksql$Dus $F(x) = \tfrac{1}{3}\arcsin(3x) + c$. Dit bestaat alleen waar $-1 \le 3x \le 1$, dus voor $-\tfrac{1}{3} \le x \le \tfrac{1}{3}$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{4}{\sqrt{16 - x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $\sqrt{a^{2} - x^{2}}$ in de noemer → nog geen standaardvorm, want achter de $1$ hoort een min en vóór het kwadraat een $1$. Haal eerst $a$ buiten de wortel: $\sqrt{a^{2} - x^{2}} = a\sqrt{1 - \left(\tfrac{x}{a}\right)^{2}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{4}{\sqrt{16 - x^{2}}}$$ksql$, 1, $ksql$Haal de $4$ buiten de wortel: $\sqrt{16 - x^{2}} = 4\sqrt{1 - \left(\tfrac{1}{4}x\right)^{2}}$. De integrand wordt $\dfrac{1}{\sqrt{1 - \left(\frac{1}{4}x\right)^{2}}}$, met kern $\tfrac{1}{4}x$ en $a = \tfrac{1}{4}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{4}{\sqrt{16 - x^{2}}}$$ksql$, 2, $ksql$Delen door $\tfrac{1}{4}$ is vermenigvuldigen met $4$, dus $F(x) = 4\arcsin\left(\tfrac{1}{4}x\right)$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{4}{\sqrt{16 - x^{2}}}$$ksql$, 3, $ksql$Dus $F(x) = 4\arcsin\left(\tfrac{1}{4}x\right) + c$. Dit bestaat alleen voor $-4 < x < 4$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{6x - x^{2} - 5}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat een kwadratische vorm met een min voor $x^{2}$ → eerst kwadraatafsplitsen, daarna de standaardvorm.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{6x - x^{2} - 5}}$$ksql$, 1, $ksql$$6x - x^{2} - 5 = 4 - (x^{2} - 6x + 9) = 4 - (x - 3)^{2}$. Haal de $2$ buiten de wortel: $\sqrt{4 - (x - 3)^{2}} = 2\sqrt{1 - \left(\tfrac{1}{2}(x - 3)\right)^{2}}$. De integrand wordt $\dfrac{\tfrac{1}{2}}{\sqrt{1 - \left(\frac{1}{2}(x - 3)\right)^{2}}}$, met kern $\tfrac{1}{2}(x - 3)$ en $a = \tfrac{1}{2}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{6x - x^{2} - 5}}$$ksql$, 2, $ksql$Delen door $\tfrac{1}{2}$ is vermenigvuldigen met $2$. De factor $\tfrac{1}{2}$ ervoor valt daartegen weg, dus er blijft $\arcsin\left(\tfrac{1}{2}(x - 3)\right)$ over.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{6x - x^{2} - 5}}$$ksql$, 3, $ksql$Dus $F(x) = \arcsin\left(\tfrac{1}{2}(x - 3)\right) + c$. Dit bestaat alleen voor $1 < x < 5$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2}}{\sqrt{1 - x^{6}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $1$ min het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g) + c$ ben je er in één stap.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2}}{\sqrt{1 - x^{6}}}$$ksql$, 1, $ksql$Neem $g(x) = x^{3}$. Dan is $g'(x) = 3x^{2}$, en die staat in de teller. Onder de wortel staat $1 - (x^{3})^{2} = 1 - g^{2}$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2}}{\sqrt{1 - x^{6}}}$$ksql$, 2, $ksql$Naar $g$ staat er $\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g = \arcsin(g)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2}}{\sqrt{1 - x^{6}}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin\left(x^{3}\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\arcsin(x)}{\sqrt{1 - x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $1$ min het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g) + c$ ben je er in één stap.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\arcsin(x)}{\sqrt{1 - x^{2}}}$$ksql$, 1, $ksql$Neem $g(x) = \arcsin(x)$. Dan is $g'(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$. In de teller staat $2\arcsin(x)$ keer die afgeleide, dus $f(x) = 2g \cdot g'$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\arcsin(x)}{\sqrt{1 - x^{2}}}$$ksql$, 2, $ksql$$\int 2g \cdot g'\,\mathrm{d}x = g^{2}$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\arcsin(x)}{\sqrt{1 - x^{2}}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin^{2}(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\mathrm{e}^{2x}}{\sqrt{1 - \mathrm{e}^{4x}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $1$ min het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g) + c$ ben je er in één stap.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\mathrm{e}^{2x}}{\sqrt{1 - \mathrm{e}^{4x}}}$$ksql$, 1, $ksql$Neem $g(x) = \mathrm{e}^{2x}$. Dan is $g'(x) = 2\mathrm{e}^{2x}$, en die staat in de teller. Onder de wortel staat $1 - \mathrm{e}^{4x} = 1 - g^{2}$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\mathrm{e}^{2x}}{\sqrt{1 - \mathrm{e}^{4x}}}$$ksql$, 2, $ksql$Naar $g$ staat er $\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g = \arcsin(g)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\mathrm{e}^{2x}}{\sqrt{1 - \mathrm{e}^{4x}}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin\left(\mathrm{e}^{2x}\right) + c$. Dit bestaat alleen waar $-1 \le \mathrm{e}^{2x} \le 1$. Omdat een e-macht positief is, blijft $x \le 0$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{9 - \ln^{2}(x)}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $\ln^{2}(x)$ en de afgeleide van $\ln(x)$ is $\tfrac{1}{x}$, en die staat als factor vooraan → substitutie. De wortel is nog niet van de vorm $\sqrt{1 - g^{2}}$, dus eerst de $3$ eruit halen.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{9 - \ln^{2}(x)}}$$ksql$, 1, $ksql$$\sqrt{9 - \ln^{2}(x)} = 3\sqrt{1 - \left(\tfrac{1}{3}\ln(x)\right)^{2}}$. Neem $g(x) = \tfrac{1}{3}\ln(x)$, dan is $g'(x) = \dfrac{1}{3x}$. Er staat dus $f(x) = \dfrac{g'}{\sqrt{1 - g^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{9 - \ln^{2}(x)}}$$ksql$, 2, $ksql$Dat is de standaardvorm naar $g$: $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{9 - \ln^{2}(x)}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin\left(\tfrac{1}{3}\ln(x)\right) + c$. Dit bestaat alleen waar $-3 \le \ln(x) \le 3$, dus voor $\mathrm{e}^{-3} \le x \le \mathrm{e}^{3}$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(x)$$ksql$, 1, $ksql$Er staat maar één factor, dus maak er zelf een product van: $h'(x) = 1$, dus $h(x) = x$, en $g(x) = \arcsin(x)$. Dan is $g'(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arcsin(x)\,\mathrm{d}x = x\arcsin(x) - \int \dfrac{x}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(x)$$ksql$, 3, $ksql$Die laatste integraal is $-\sqrt{1 - x^{2}}$, want $\left[\sqrt{1 - x^{2}}\right]' = \dfrac{-x}{\sqrt{1 - x^{2}}}$. Met het minteken ervoor wordt het een plus: $F(x) = x\arcsin(x) + \sqrt{1 - x^{2}} + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(x)$$ksql$, 1, $ksql$Weer één factor: $h'(x) = 1$ en $h(x) = x$, met $g(x) = \arctan(x)$. Dan is $g'(x) = \dfrac{1}{x^{2} + 1}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arctan(x)\,\mathrm{d}x = x\arctan(x) - \int \dfrac{x}{x^{2} + 1}\,\mathrm{d}x$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(x)$$ksql$, 3, $ksql$$\left[x^{2} + 1\right]' = 2x$, en in de teller staat de helft daarvan. Dus $\int \dfrac{x}{x^{2} + 1}\,\mathrm{d}x = \tfrac{1}{2}\ln\left(x^{2} + 1\right)$. Samen: $F(x) = x\arctan(x) - \tfrac{1}{2}\ln\left(x^{2} + 1\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(3x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(3x)$$ksql$, 1, $ksql$$h'(x) = 1$, dus $h(x) = x$, en $g(x) = \arcsin(3x)$. Met de kettingregel is $g'(x) = \dfrac{3}{\sqrt{1 - 9x^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(3x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arcsin(3x)\,\mathrm{d}x = x\arcsin(3x) - \int \dfrac{3x}{\sqrt{1 - 9x^{2}}}\,\mathrm{d}x$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(3x)$$ksql$, 3, $ksql$$\left[\sqrt{1 - 9x^{2}}\right]' = \dfrac{-9x}{\sqrt{1 - 9x^{2}}}$, en de integrand van de rest is daar $-\tfrac{1}{3}$ van. De rest-integraal is dus $-\tfrac{1}{3}\sqrt{1 - 9x^{2}}$. Met het minteken ervoor: $F(x) = x\arcsin(3x) + \tfrac{1}{3}\sqrt{1 - 9x^{2}} + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(2x)$$ksql$, 1, $ksql$$h'(x) = 1$ en $h(x) = x$, met $g(x) = \arctan(2x)$. Dan is $g'(x) = \dfrac{2}{4x^{2} + 1}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arctan(2x)\,\mathrm{d}x = x\arctan(2x) - \int \dfrac{2x}{4x^{2} + 1}\,\mathrm{d}x$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(2x)$$ksql$, 3, $ksql$$\left[4x^{2} + 1\right]' = 8x$, en $2x$ is daar $\tfrac{1}{4}$ van. Dus de rest is $\tfrac{1}{4}\ln\left(4x^{2} + 1\right)$. Samen: $F(x) = x\arctan(2x) - \tfrac{1}{4}\ln\left(4x^{2} + 1\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \arcsin(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \arcsin(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$$h'(x) = 1$, dus $h(x) = x$, en $g(x) = \arcsin(2x)$ met $g'(x) = \dfrac{2}{\sqrt{1 - 4x^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \arcsin(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arcsin(2x)\,\mathrm{d}x = x\arcsin(2x) - \int \dfrac{2x}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$. Die laatste integraal is $-\tfrac{1}{2}\sqrt{1 - 4x^{2}}$, want $\left[\sqrt{1 - 4x^{2}}\right]' = \dfrac{-4x}{\sqrt{1 - 4x^{2}}}$. Dus $F(x) = x\arcsin(2x) + \tfrac{1}{2}\sqrt{1 - 4x^{2}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \arcsin(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[x\arcsin(2x) + \tfrac{1}{2}\sqrt{1 - 4x^{2}}\right]_{0}^{\frac{1}{2}} = \left(\tfrac{1}{2} \cdot \tfrac{1}{2}\pi + 0\right) - \left(0 + \tfrac{1}{2}\right) = \tfrac{1}{4}\pi - \tfrac{1}{2}$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 1, $ksql$Er staat al de standaardvorm, met kern $x$ en $a = 1$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $F(x) = \arcsin(x)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 3, $ksql$$\big[\arcsin(x)\big]_{0}^{\frac{1}{2}} = \arcsin\left(\tfrac{1}{2}\right) - \arcsin(0) = \tfrac{1}{6}\pi - 0 = \tfrac{1}{6}\pi$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 1, $ksql$$4x^{2} = (2x)^{2}$, dus $\dfrac{2}{\sqrt{1 - (2x)^{2}}}$: kern $2x$ met $a = 2$, en er staat al een factor $2$ voor.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Delen door $a = 2$ valt tegen die factor $2$ weg. Een primitieve is $F(x) = \arcsin(2x)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = \tfrac{1}{2}$ is de kern $1$ en bij $x = 0$ is de kern $0$: $\arcsin(1) - \arcsin(0) = \tfrac{1}{2}\pi$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $\sqrt{a^{2} - x^{2}}$ in de noemer → nog geen standaardvorm, want achter de $1$ hoort een min en vóór het kwadraat een $1$. Haal eerst $a$ buiten de wortel: $\sqrt{a^{2} - x^{2}} = a\sqrt{1 - \left(\tfrac{x}{a}\right)^{2}}$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$$ksql$, 1, $ksql$$\sqrt{9 - x^{2}} = 3\sqrt{1 - \left(\tfrac{1}{3}x\right)^{2}}$. De integrand wordt $\dfrac{\tfrac{1}{3}}{\sqrt{1 - \left(\frac{1}{3}x\right)^{2}}}$, met kern $\tfrac{1}{3}x$ en $a = \tfrac{1}{3}$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Delen door $\tfrac{1}{3}$ is vermenigvuldigen met $3$. De factor $\tfrac{1}{3}$ valt daartegen weg: $F(x) = \arcsin\left(\tfrac{1}{3}x\right)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = 3$ is de kern $1$ en bij $x = 0$ is de kern $0$: $\arcsin(1) - \arcsin(0) = \tfrac{1}{2}\pi$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{\sqrt{4 - x^{4}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: onder de wortel staat een getal min $x^{4}$, en in de teller staat een $x$ → eerst het getal buiten de wortel halen, daarna substitueren.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{\sqrt{4 - x^{4}}}\,\mathrm{d}x$$ksql$, 1, $ksql$$\sqrt{4 - x^{4}} = 2\sqrt{1 - \left(\tfrac{x^{2}}{2}\right)^{2}}$. Neem $g(x) = \tfrac{x^{2}}{2}$, dan is $g'(x) = x$. In de teller staat na het delen $\tfrac{1}{2} \cdot 2x = x$, en dat is precies $g'$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{\sqrt{4 - x^{4}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Naar $g$ staat er $\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g = \arcsin(g)$, dus $F(x) = \arcsin\left(\tfrac{x^{2}}{2}\right)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{\sqrt{4 - x^{4}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = 1$ is de kern $\tfrac{1}{2}$ en bij $x = 0$ is de kern $0$: $\arcsin\left(\tfrac{1}{2}\right) - 0 = \tfrac{1}{6}\pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = \tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V) = \displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$. Op $\left[0, \tfrac{1}{2}\right]$ is $f$ positief.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = \tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Er staat al de standaardvorm, met kern $x$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = \tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Deel 2: $F(x) = \arcsin(x)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = \tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Deel 3: $O(V) = \arcsin\left(\tfrac{1}{2}\right) - \arcsin(0) = \tfrac{1}{6}\pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V) = \displaystyle\int_{0}^{1} \dfrac{2}{\sqrt{4 - x^{2}}}\,\mathrm{d}x$. Op $[0, 1]$ is $f$ positief.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\sqrt{4 - x^{2}} = 2\sqrt{1 - \left(\tfrac{1}{2}x\right)^{2}}$. De integrand wordt $\dfrac{1}{\sqrt{1 - \left(\frac{1}{2}x\right)^{2}}}$, met kern $\tfrac{1}{2}x$ en $a = \tfrac{1}{2}$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Deel 2: delen door $\tfrac{1}{2}$ is vermenigvuldigen met $2$, dus $F(x) = 2\arcsin\left(\tfrac{1}{2}x\right)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Deel 3: bij $x = 1$ is de kern $\tfrac{1}{2}$ en bij $x = 0$ is de kern $0$. $O(V) = 2\arcsin\left(\tfrac{1}{2}\right) = 2 \cdot \tfrac{1}{6}\pi = \tfrac{1}{3}\pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = -2$ en $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V) = \displaystyle\int_{-2}^{2} \dfrac{1}{\sqrt{4 - x^{2}}}\,\mathrm{d}x$. Op $\langle-2, 2\rangle$ is $f$ positief.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = -2$ en $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\sqrt{4 - x^{2}} = 2\sqrt{1 - \left(\tfrac{1}{2}x\right)^{2}}$. De integrand wordt $\dfrac{\tfrac{1}{2}}{\sqrt{1 - \left(\frac{1}{2}x\right)^{2}}}$, met kern $\tfrac{1}{2}x$ en $a = \tfrac{1}{2}$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = -2$ en $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Deel 2: de factor $\tfrac{1}{2}$ en het delen door $\tfrac{1}{2}$ vallen tegen elkaar weg. $F(x) = \arcsin\left(\tfrac{1}{2}x\right)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = -2$ en $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Deel 3: $\arcsin(1) - \arcsin(-1) = \tfrac{1}{2}\pi - \left(-\tfrac{1}{2}\pi\right) = \pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 1$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{3}\pi$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V_p) = \displaystyle\int_{0}^{p} \dfrac{2}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$. De voorwaarde $p < 1$ staat erbij omdat $f$ buiten $\langle-1, 1\rangle$ niet bestaat.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 1$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{3}\pi$.$ksql$, 1, $ksql$Er staat twee keer de standaardvorm, met kern $x$ en $a = 1$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 1$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{3}\pi$.$ksql$, 2, $ksql$Deel 2: $F(x) = 2\arcsin(x)$. Omdat $\arcsin(0) = 0$ is $O(V_p) = 2\arcsin(p)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 1$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{3}\pi$.$ksql$, 3, $ksql$Deel 3: $2\arcsin(p) = \tfrac{1}{3}\pi$ geeft $\arcsin(p) = \tfrac{1}{6}\pi$. Dus $p = \sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$. Dat is inderdaad kleiner dan $1$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{6}{\sqrt{36 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 6$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V_p) = \displaystyle\int_{0}^{p} \dfrac{6}{\sqrt{36 - x^{2}}}\,\mathrm{d}x$. De voorwaarde $p < 6$ staat erbij omdat $f$ buiten $\langle-6, 6\rangle$ niet bestaat.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{6}{\sqrt{36 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 6$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 1, $ksql$$\sqrt{36 - x^{2}} = 6\sqrt{1 - \left(\tfrac{1}{6}x\right)^{2}}$. De integrand wordt $\dfrac{1}{\sqrt{1 - \left(\frac{1}{6}x\right)^{2}}}$, met kern $\tfrac{1}{6}x$ en $a = \tfrac{1}{6}$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{6}{\sqrt{36 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 6$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 2, $ksql$Deel 2: delen door $\tfrac{1}{6}$ is vermenigvuldigen met $6$, dus $F(x) = 6\arcsin\left(\tfrac{1}{6}x\right)$. Omdat $\arcsin(0) = 0$ is $O(V_p) = 6\arcsin\left(\tfrac{1}{6}p\right)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{6}{\sqrt{36 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 6$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 3, $ksql$Deel 3: $6\arcsin\left(\tfrac{1}{6}p\right) = \pi$ geeft $\arcsin\left(\tfrac{1}{6}p\right) = \tfrac{1}{6}\pi$. Dus $\tfrac{1}{6}p = \sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$ en $p = 3$. Dat is kleiner dan $6$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_waarden' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_arctangens' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3a_waarden hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_vergelijking' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_arctangens' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3a_vergelijking hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_afgeleide' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3a_afgeleide hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_standaard' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3a_standaard hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_kern' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3a_kern hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_bepaald_exact' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_bepaald' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3a_bepaald_exact hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3b_herschrijven' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3b_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3b_herschrijven hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3b_kwadraat' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3b_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3b_kwadraat hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3b_bepaald_exact' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3b_bepaald' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3b_bepaald_exact hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3b_oppervlakte' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3b_toepassing' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3b_oppervlakte hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_waarden' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_arcsinus' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_waarden hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_vergelijking' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_arcsinus' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_vergelijking hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_standaard' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_standaard hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_kern' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_kern hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_partieel' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_partieel hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_bepaald_exact' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_bepaald' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_bepaald_exact hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_oppervlakte' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_toepassing' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k3c_oppervlakte hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topic_clusters_new cl ON cl.id = vr.cluster_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  JOIN (VALUES
    ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(-\sqrt{3}\right) + \arctan(1)$$ksql$),
    ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{5}{6}\pi\right)\right)$$ksql$),
    ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $2\arctan(x) = \tfrac{1}{3}\pi$$ksql$),
    ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(3x) = 1{,}2$. Rond af op drie decimalen.$ksql$),
    ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(5x - 1)$$ksql$),
    ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x^{2}\arctan(x)$$ksql$),
    ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2} + 1}{x^{2} + 1}$$ksql$),
    ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6x - 2}{x^{2} + 1}$$ksql$),
    ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(3x + 1)^{2} + 1}$$ksql$),
    ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{4x^{3}}{x^{8} + 1}$$ksql$),
    ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$),
    ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{4x^{3}}{x^{8} + 1}\,\mathrm{d}x$$ksql$),
    ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{4}{x^{2} + 4}$$ksql$),
    ('k3b_primitiveren', 'k3b_herschrijven', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 8}{x^{2} + 4}$$ksql$),
    ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 6x + 10}$$ksql$),
    ('k3b_primitiveren', 'k3b_kwadraat', $ksql$Primitiveer: $f(x) = \dfrac{8}{x^{2} - 2x + 5}$$ksql$),
    ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{x^{2} + 9}\,\mathrm{d}x$$ksql$),
    ('k3b_bepaald', 'k3b_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{1}^{1 + \sqrt{3}} \dfrac{3}{x^{2} - 2x + 2}\,\mathrm{d}x$$ksql$),
    ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Gegeven is de functie $f(x) = \dfrac{18}{x^{2} + 6x + 18}$. Bereken exact het maximum van $f$.$ksql$),
    ('k3b_toepassing', 'k3b_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{2}\pi$.$ksql$),
    ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\right)$$ksql$),
    ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin(-1)$$ksql$),
    ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{2}\right) + \arcsin\left(-\tfrac{1}{2}\right)$$ksql$),
    ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $2\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) - \arcsin(1)$$ksql$),
    ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{7}{6}\pi\right)\right)$$ksql$),
    ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{4}\pi$$ksql$),
    ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(2x) = -\tfrac{1}{6}\pi$$ksql$),
    ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \pi$$ksql$),
    ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = 0{,}8$. Rond af op drie decimalen.$ksql$),
    ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 9x^{2}}}$$ksql$),
    ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{4}{\sqrt{16 - x^{2}}}$$ksql$),
    ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{6x - x^{2} - 5}}$$ksql$),
    ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{3x^{2}}{\sqrt{1 - x^{6}}}$$ksql$),
    ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\arcsin(x)}{\sqrt{1 - x^{2}}}$$ksql$),
    ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2\mathrm{e}^{2x}}{\sqrt{1 - \mathrm{e}^{4x}}}$$ksql$),
    ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{9 - \ln^{2}(x)}}$$ksql$),
    ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(x)$$ksql$),
    ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(x)$$ksql$),
    ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(3x)$$ksql$),
    ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(2x)$$ksql$),
    ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \arcsin(2x)\,\mathrm{d}x$$ksql$),
    ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$),
    ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$),
    ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{3} \dfrac{1}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$$ksql$),
    ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{\sqrt{4 - x^{4}}}\,\mathrm{d}x$$ksql$),
    ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = \tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$),
    ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$),
    ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$, de $x$-as en de lijnen $x = -2$ en $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$),
    ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2}{\sqrt{1 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 1$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \tfrac{1}{3}\pi$.$ksql$),
    ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{6}{\sqrt{36 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 6$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$)
  ) AS v(topic_slug, cluster_slug, latex_body)
    ON t.slug = v.topic_slug AND t.site = 'integralen'
   AND cl.slug = v.cluster_slug AND cl.topic_id = t.id
   AND vr.latex_body = v.latex_body;
  IF n <> 200 THEN RAISE EXCEPTION 'Deze vragen horen samen 200 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
